-- =============================================================================
-- SEED DATA: MODUL 6 - SUMBER DAYA PRAJURIT & PANGKAT ANGKATAN LAUT
-- =============================================================================

ON CONFLICT (rank_id) DO UPDATE SET rank_name = EXCLUDED.rank_name, rank_code = EXCLUDED.rank_code;

ON CONFLICT (corps_id) DO UPDATE SET corps_name = EXCLUDED.corps_name;

ON CONFLICT (personnel_id) DO UPDATE SET full_name = EXCLUDED.full_name, current_position = EXCLUDED.current_position;

ON CONFLICT (qualification_id) DO UPDATE SET qualification_name = EXCLUDED.qualification_name;


ON CONFLICT (personnel_id, qualification_id) DO NOTHING;

ON CONFLICT (assignment_id) DO NOTHING;

ON CONFLICT (allowance_id) DO NOTHING;
